#!/usr/bin/env python3
"""Real-browser preview journeys. No API stubs; uses the supplied Portal login and local preview data.
Run: python tests/browser-journeys.py --base http://127.0.0.1:8000 --browser /usr/bin/chromium
"""
import argparse,json,time
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--base',default='http://127.0.0.1:8000');parser.add_argument('--browser',default='/usr/bin/chromium');parser.add_argument('--out',type=Path,default=Path(__file__).parent.parent/'evidence');args=parser.parse_args();args.out.mkdir(parents=True,exist_ok=True)
results=[]
def check(name,condition=True):
 assert condition,name
 results.append({'name':name,'passed':True});print('PASS',name,flush=True)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=args.browser,headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':1440,'height':1000},reduced_motion='reduce');page.set_default_timeout(6000)
 errors=[];api_requests=[]
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.on('request',lambda r:api_requests.append(r.url) if '/api/' in r.url else None)
 page.goto(args.base+'/portal-studio/index.html?preview=live&role=administrator')
 page.locator('#auth-form button').click()
 check('Existing preview sign-in opens Overview',page.locator('main[data-screen=overview]').count()==1)
 def visit(key,v='1',role='administrator'):
  page.evaluate('([key,r])=>{role=r;navigate(key)}',[key,role]);page.locator('#content>label>select').select_option(str(v));page.locator('.as-root').wait_for()
 def state():return page.evaluate('JSON.parse(localStorage.getItem("portal-academic-setup:preview:v2")||"null")')
 def act(name,id=None):
  sel=f'[data-as-action="{name}"]'+(f'[data-id="{id}"]' if id else '')
  target=page.locator('.as-dialog[open] '+sel)
  (target if target.count() else page.locator('.as-root '+sel)).first.click()
 def dialog():return page.locator('.as-dialog[open]')
 def save():dialog().locator('button[type=submit]').click()
 def close():dialog().locator('[data-as-close]').click()
 def fill_course(code,name):
  dialog().locator('[name=code]').fill(code);dialog().locator('[name=name]').fill(name);dialog().locator('[name=credits]').fill('4')
 visit('courses',3)
 page.locator('[data-action=add-course]').click();save()
 check('Course form shows validation without partial creation',dialog().locator('.as-errors').count()>=1 and state() is None)
 fill_course('DEMO902','Design verification elective');save()
 check('Course creation persists',any(c['code']=='DEMO902' for c in state()['courses']))
 course=next(c for c in state()['courses'] if c['code']=='DEMO902')
 visit('courses',1);act('course-edit',course['id']);dialog().locator('[name=name]').fill('Edited verification elective');save()
 check('Course editing updates the same record',sum(c['code']=='DEMO902' for c in state()['courses'])==1 and next(c for c in state()['courses'] if c['id']==course['id'])['name'].startswith('Edited'))
 page.locator('[data-action=import-csv]').click();before=len(state()['courses'])
 dialog().locator('textarea[name=csv]').fill('code,name,credits,type,major,semester,seasons,prerequisites\nDEMO903,Valid row,4,elective,CS,7,winter,\nDEMO904,Bad row,nope,elective,CS,7,winter,\n');save()
 check('CSV errors are row-addressed and atomic','Row 3' in dialog().inner_text() and len(state()['courses'])==before)
 dialog().locator('textarea[name=csv]').fill('code,name,credits,type,major,semester,seasons,prerequisites\nDEMO903,Valid row,4,elective,CS,7,winter,\n');save()
 check('CSV preview does not commit before confirmation',len(state()['courses'])==before and dialog().get_by_role('button',name='Import valid batch').count()==1)
 save();check('Valid CSV batch commits once',sum(c['code']=='DEMO903' for c in state()['courses'])==1)
 page.locator('[data-action=import-csv]').click();dialog().locator('textarea[name=csv]').fill('code,name,credits,type,major,semester,seasons,prerequisites\nDEMO903,Updated import,5,elective,CS,7,winter,\n');save();save()
 check('CSV upsert avoids duplicate codes',sum(c['code']=='DEMO903' for c in state()['courses'])==1 and next(c for c in state()['courses'] if c['code']=='DEMO903')['credits']==5)
 act('course-view','CSEN501');page.locator('#content>label>select').select_option('1');act('delete-course','CSEN501');save()
 check('Referenced course deletion is blocked','protected' in dialog().inner_text().lower() and any(c['id']=='CSEN501' for c in state()['courses']));close()
 visit('courses');act('course-view',course['id']);page.locator('#content>label>select').select_option('4');act('delete-course',course['id']);save()
 check('Unused course deletion works',all(c['id']!=course['id'] for c in state()['courses']))
 visit('terms',5);act('term-edit','w26');dialog().locator('[name=registrationStart]').fill('2026-11-23');save()
 check('Term edits update preview milestones',next(t for t in state()['terms'] if t['id']=='w26')['registrationStart']=='2026-11-23' and page.evaluate('academicTerms.find(t=>t.name==="Winter 2026").opens')=='2026-11-23')
 act('term-edit','w26');dialog().locator('[name=teachingEnd]').fill('2030-01-01');save()
 check('Term dates reject teaching beyond term end',dialog().locator('.as-errors').count()>=1);close()
 visit('offerings',1);act('offering-view','w26-CSEN701');act('slot-edit','w26-CSEN701-lecture-4');dialog().locator('[name=capacity]').fill('1');save()
 check('Assigned capacity cannot be reduced below occupancy','assigned' in dialog().inner_text().lower() and dialog().locator('.as-errors').count()>=1);close()
 act('publication','w26-CSEN701');save()
 check('Referenced offering cannot be unpublished',dialog().locator('.as-errors').count()>=1 and next(o for o in state()['offerings'] if o['id']=='w26-CSEN701')['published']);close()
 page.locator('[data-action=add-offering]').click();dialog().locator('[name=course]').select_option('CSEN501');dialog().locator('[name=instructors]').fill('Test instructor | test@guc.edu.eg');dialog().locator('[name=eligible]').fill('CS | 7 |');save()
 check('New offering starts as draft',dialog().count()==1 and 'Draft' in dialog().inner_text())
 offering=next(o for o in state()['offerings'] if o['course']=='CSEN501' and o['term']=='w26')
 act('publication',offering['id']);save();check('Publication requires teaching groups',dialog().locator('.as-errors').count()>=1);close()
 act('offering-view',offering['id']);page.locator('.as-dialog [data-as-action=slot-edit]').first.click();dialog().locator('[name=day]').select_option('Friday');dialog().locator('[name=room]').fill('C9.999');save()
 check('Teaching group saves and returns to offering',len(next(o for o in state()['offerings'] if o['id']==offering['id'])['slots'])==1)
 act('publication',offering['id']);save();check('Ready offering publishes',next(o for o in state()['offerings'] if o['id']==offering['id'])['published'])
 act('publication',offering['id']);save();check('Unused offering can return to draft',not next(o for o in state()['offerings'] if o['id']==offering['id'])['published'])
 act('offering-view',offering['id']);act('delete-offering',offering['id']);save();check('Unused offering deletion removes its groups',all(o['id']!=offering['id'] for o in state()['offerings']))
 visit('copy-offerings',7);act('copy-review')
 check('Copy review separates new and existing offerings','2 new unpublished drafts' in dialog().inner_text() and '4 existing offerings skipped' in dialog().inner_text());save()
 check('Copy resets publication and occupancy',all(not o['published'] and all(s['assigned']==0 for s in o['slots']) for o in state()['offerings'] if o['term']=='w26' and o['course'] in ['ELCT701','MATH701']));close()
 act('copy-review');save();check('Repeated copy is duplicate-safe','0 unpublished drafts created' in dialog().inner_text());close()
 visit('templates',3,'coordinator');act('select','group-4');act('template-view','group-4');page.locator('#content>label>select').select_option('7')
 select=page.locator('[data-as-template-slot="0"][data-type=lecture]');select.select_option('')
 page.locator('[data-action=publish]').click();check('Template refuses missing component selection',page.locator('.as-errors').count()>0)
 select=page.locator('[data-as-template-slot="0"][data-type=lecture]');select.select_option('w26-CSEN701-lecture-4')
 page.locator('[data-action=publish]').click();check('Template saves validated component selection',next(t for t in state()['templates'] if t['id']=='group-4')['version']==2)
 visit('group-assignments',7,'coordinator');act('assignment','student-1');dialog().locator('select[name=template]').select_option('group-1')
 check('Assignment review shows before and after',dialog().locator('.as-before-after').count()==1 and 'Current · Unassigned' in dialog().inner_text());save()
 check('Assignment generates processed schedule',state()['students'][1]['schedule']['status']=='processed' and state()['students'][1]['assignment']=='group-1')
 act('assignment','student-0');dialog().locator('select[name=template]').select_option('group-1');save()
 check('Reassignment retains history and updates destination',state()['students'][0]['assignment']=='group-1' and len(state()['students'][0]['history'])==1)
 act('unassign','student-1');save();check('Unassignment releases seats and preserves history',state()['students'][1]['assignment'] is None and len(state()['students'][1]['history'])==2)
 visit('courses',4,'coordinator');check('Coordinator catalogue is read-only',page.locator('[data-action=add-course]').count()==0 and page.locator('[data-as-action=course-edit]').count()==0)
 visit('group-assignments',4,'administrator');check('Administrator can inspect but not mutate assignments',page.locator('[data-as-action=unassign]').count()==0 and page.locator('[data-as-action=assignment]').first.inner_text()=='View schedule')
 visit('templates',2,'administrator');check('Unauthorized template route is denied','not available for your role' in page.locator('.as-root').inner_text())
 visit('courses',5);page.locator('a[data-page=terms]').first.click();page.locator('#content>label>select').select_option('9');page.locator('a[data-page=courses]').first.click()
 check('Each page remembers its own variant',page.locator('#content>label>select').input_value()=='5')
 page.locator('a[data-page=terms]').first.click();check('Second page keeps independent choice',page.locator('#content>label>select').input_value()=='9')
 page.locator('.account-button').click();page.locator('#account-menu button[data-action=sign-out]').click();check('Existing sign-out reaches login',page.locator('#auth-form').count()==1)
 page.locator('#auth-form button').click();check('Sign-in returns to Overview',page.locator('main[data-screen=overview]').count()==1)
 page.locator('a[data-page=courses]').first.click();check('Variant survives sign-out and sign-in',page.locator('#content>label>select').input_value()=='5')
 page.locator('#content>label>select').select_option('0');check('Original renderer remains available',page.locator('.as-root').count()==0 and page.locator('[data-action=add-course]').count()==1)
 page.locator('[data-action=add-course]').click();check('Original action still opens original form',page.locator('#dialog[open]').count()==1);page.locator('#dialog [data-action=close-dialog]').first.click()
 visit('courses',1);page.locator('[data-action=add-course]').click();fill_course('DEMO905','Storage error test')
 page.evaluate('()=>{window.asSavedSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k==="portal-academic-setup:preview:v2")throw new DOMException("quota","QuotaExceededError");return window.asSavedSet.call(this,k,v)}}');save()
 check('Storage failure leaves data uncommitted',dialog().locator('.as-errors').count()>=1 and all(c['code']!='DEMO905' for c in state()['courses']));page.evaluate('()=>{Storage.prototype.setItem=window.asSavedSet}');close()
 page.locator('[data-action=add-course]').click();fill_course('DEMO906','Stale write test');page.evaluate('let s=JSON.parse(localStorage.getItem("portal-academic-setup:preview:v2"));s.revision++;localStorage.setItem("portal-academic-setup:preview:v2",JSON.stringify(s))');save()
 check('Stale-tab write is rejected','changed in another tab' in dialog().inner_text() and all(c['code']!='DEMO906' for c in state()['courses']));close()
 check('Preview never calls production APIs',not api_requests)
 check('Browser has no unhandled JavaScript errors',not errors)
 page.screenshot(path=str(args.out/'journey-final-desktop.png'),full_page=True)
 browser.close()
 report={'suite':'browser-journeys','base':args.base,'passed':len(results),'failed':0,'cases':results,'javascriptErrors':errors,'apiRequests':api_requests}
 (args.out/'browser-journeys.json').write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({'passed':len(results),'failed':0}))
